package com.bank.adjust;

import java.util.logging.Logger;

public class AdjustmentCounter {

    private static final Logger log = Logger.getLogger(AdjustmentCounter.class.getName());

    public int countAssignments(int[] amounts, int target) {
        int total = 0;
        for (int a : amounts) total += a;
        if (total + target < 0 || (total + target) % 2 != 0) {
            log.warning("No valid sign assignment exists");
            return 0;                                  // P would be fractional/negative
        }
        int p = (total + target) / 2;                  // positive-subset target
        int[] dp = new int[p + 1];
        dp[0] = 1;                                      // one way to pick empty subset
        for (int num : amounts) {
            for (int s = p; s >= num; s--) {            // DOWNWARD ⇒ each number once
                dp[s] += dp[s - num];
            }
        }
        int result = dp[p];
        log.info(() -> "Valid sign assignments = " + result);
        return result;
    }
}
