package com.bank.adjust;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class TargetSumDemo {

    private static final Logger log = Logger.getLogger(TargetSumDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Adjustment Counter (Target Sum)");
        AdjustmentCounter counter = new AdjustmentCounter();
        log.info("{1,1,1,1,1}, target 3 → " + counter.countAssignments(new int[]{1,1,1,1,1}, 3)); // 5
        log.info("{1}, target 2 → " + counter.countAssignments(new int[]{1}, 2));                  // 0
    }
}
